-- car-rental (pending)
insert into quiz.assignments (slug, sort_order, is_active, title_sk, title_en, brief_sk, brief_en,
                              max_points, time_limit_ms, scenarios, design, reference_solution)
values ($q$car-rental$q$, 30, true, $q$Požičovňa áut Rýchlik$q$, $q$Rychlik Car Rental$q$,
        ($q$"Požičovňa áut Rýchlik v Žiline prenajíma autá a chce malý konzolový program pre svoju kanceláriu. Každé auto má evidenčné číslo (ŠPZ) a model. Každý zákazník má meno a telefónne číslo a kancelária musí vedieť, ktorý zákazník má ktoré auto.\n\nNové auto sa pridá príkazom `addcar`, za ktorým nasleduje ŠPZ a model. Program odpovie `Car BA123AB added.`\n\nAuto sa prenajme príkazom `rent`, za ktorým nasleduje ŠPZ, meno zákazníka a jeho telefónne číslo. Ak je auto voľné, program odpovie `Car BA123AB rented to Peter.` Ak je už prenajaté, odpovie `Car BA123AB is already rented.` Ak auto s takou ŠPZ neexistuje, odpovie `Car XX999XX does not exist.`\n\nPríkaz `customer`, za ktorým nasleduje meno, vypíše každé auto prenajaté zákazníkovi s týmto menom na samostatný riadok, napríklad `BA123AB Skoda`, v poradí, v akom boli autá pridané. Ak zákazník nemá žiadne auto, vypíše `Peter has no cars.` (s menom, na ktoré sa pýtame).\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"Rychlik Car Rental in Žilina rents out cars and wants a small console program for its office. Every car has a licence plate and a model. Every customer has a name and a phone number, and the office must know which customer has which car.\n\nA new car is added with the command `addcar`, followed by the plate and the model. The program replies `Car BA123AB added.`\n\nA car is rented with `rent`, followed by the plate, the customer's name and phone number. If the car is available, the program replies `Car BA123AB rented to Peter.` If it is already rented, it replies `Car BA123AB is already rented.` If there is no car with that plate, it replies `Car XX999XX does not exist.`\n\nThe command `customer`, followed by a name, lists every car rented to a customer with that name on its own line, like `BA123AB Skoda`, in the order the cars were added. If that customer has no car, it prints `Peter has no cars.` (with the name that was asked for).\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie auta","name_en":"Adding a car","input":"addcar BA123AB Skoda\naddcar KE456CD Kia\nexit\n","expected":"Car BA123AB added.\nCar KE456CD added.\n","points":15},{"name_sk":"Prenájom voľného auta priradí zákazníka","name_en":"Renting a free car assigns the customer","input":"addcar BA123AB Skoda\naddcar KE456CD Kia\nrent KE456CD Peter 0901111222\ncustomer Peter\nexit\n","expected":"Car BA123AB added.\nCar KE456CD added.\nCar KE456CD rented to Peter.\nKE456CD Kia\n","points":25},{"name_sk":"Prenájom prenajatého auta zlyhá","name_en":"Renting a car that is already rented fails","input":"addcar BA123AB Skoda\nrent BA123AB Peter 0901111222\nrent BA123AB Jana 0902333444\ncustomer Jana\nexit\n","expected":"Car BA123AB added.\nCar BA123AB rented to Peter.\nCar BA123AB is already rented.\nJana has no cars.\n","points":20},{"name_sk":"Zoznam áut zákazníka je presný","name_en":"The list of a customer's cars is exact","input":"addcar BA123AB Skoda\naddcar KE456CD Kia\naddcar NR789EF Ford\ncustomer Peter\nrent NR789EF Peter 0901111222\nrent BA123AB Peter 0901111222\nrent KE456CD Jana 0902333444\ncustomer Peter\ncustomer Jana\nexit\n","expected":"Car BA123AB added.\nCar KE456CD added.\nCar NR789EF added.\nPeter has no cars.\nCar NR789EF rented to Peter.\nCar BA123AB rented to Peter.\nCar KE456CD rented to Jana.\nBA123AB Skoda\nNR789EF Ford\nKE456CD Kia\n","points":25},{"name_sk":"Prenájom neexistujúceho auta zlyhá","name_en":"Renting a car that does not exist fails","input":"addcar BA123AB Skoda\nrent XX999XX Peter 0901111222\ncustomer Peter\nexit\n","expected":"Car BA123AB added.\nCar XX999XX does not exist.\nPeter has no cars.\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Car","role":"item","properties":["string Plate","string Model","Customer? Customer","bool IsRented (Customer != null)"]},{"name":"Customer","role":"person","properties":["string Name","string Phone"]},{"name":"RentalCompany","role":"manager","properties":["string Name","List<Car> Cars"],"operations":["AddCar(plate, model)","Rent(plate, customer)","CarsOf(name)"]}],"link":"Car.Customer → Customer (one-way: the car knows who rents it)","storage":"List<Car> in RentalCompany"}$q$::jsonb,
        ($q$"// Reference solution – Rychlik Car Rental. Hidden from students; used to validate the scenarios.\nvar company = new RentalCompany(\"Rychlik\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addcar\")\n    {\n        Console.WriteLine(company.AddCar(parts[1], parts[2]));\n    }\n    else if (command == \"rent\")\n    {\n        Console.WriteLine(company.Rent(parts[1], new Customer(parts[2], parts[3])));\n    }\n    else if (command == \"customer\")\n    {\n        string name = parts[1];\n        List<Car> cars = company.CarsOf(name);\n        if (cars.Count == 0) Console.WriteLine($\"{name} has no cars.\");\n        foreach (Car car in cars) Console.WriteLine($\"{car.Plate} {car.Model}\");\n    }\n}\n\nclass Car\n{\n    public string Plate { get; }\n    public string Model { get; }\n    public Customer? Customer { get; set; }\n    public bool IsRented => Customer != null;\n\n    public Car(string plate, string model)\n    {\n        Plate = plate;\n        Model = model;\n    }\n}\n\nclass Customer\n{\n    public string Name { get; }\n    public string Phone { get; }\n\n    public Customer(string name, string phone)\n    {\n        Name = name;\n        Phone = phone;\n    }\n}\n\nclass RentalCompany\n{\n    public string Name { get; }\n    private readonly List<Car> cars = new List<Car>();\n\n    public RentalCompany(string name)\n    {\n        Name = name;\n    }\n\n    public string AddCar(string plate, string model)\n    {\n        cars.Add(new Car(plate, model));\n        return $\"Car {plate} added.\";\n    }\n\n    public string Rent(string plate, Customer customer)\n    {\n        Car? car = cars.Find(c => c.Plate == plate);\n        if (car == null) return $\"Car {plate} does not exist.\";\n        if (car.IsRented) return $\"Car {plate} is already rented.\";\n        car.Customer = customer;\n        return $\"Car {plate} rented to {customer.Name}.\";\n    }\n\n    public List<Car> CarsOf(string name)\n    {\n        return cars.FindAll(c => c.Customer != null && c.Customer.Name == name);\n    }\n}\n"$q$::jsonb #>> '{}'))
