-- gym (pending)
insert into quiz.assignments (slug, sort_order, is_active, title_sk, title_en, brief_sk, brief_en,
                              max_points, time_limit_ms, scenarios, design, reference_solution)
values ($q$gym$q$, 40, true, $q$Fitnes centrum Sila$q$, $q$Sila Fitness$q$,
        ($q$"Fitnes centrum Sila v Nitre prenajíma svojim členom skrinky na celú sezónu. Každá skrinka má číslo a veľkosť, small alebo large. Každý člen má meno a číslo členskej karty a recepcia musí vedieť, ktorý člen používa ktorú skrinku.\n\nRecepcia pridá skrinku príkazom `addlocker`, za ktorým nasleduje jej číslo a veľkosť. Program odpovie `Locker 12 added.`\n\nSkrinka sa pridelí členovi príkazom `assign`, za ktorým nasleduje číslo skrinky, meno člena a číslo jeho karty. Ak je skrinka voľná, program odpovie `Locker 12 assigned to Marek.` Ak ju už niekto používa, odpovie `Locker 12 is taken.` Ak taká skrinka neexistuje, odpovie `Locker 99 does not exist.`\n\nPríkaz `count` vypíše, koľko skriniek je voľných a koľko obsadených, presne v tvare `Free lockers: 2, taken lockers: 1.`\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"Sila Fitness in Nitra lends lockers to its members for the whole season. Every locker has a number and a size, small or large. Every member has a name and a membership card number, and the reception must know which member uses which locker.\n\nReception adds a locker with the command `addlocker`, followed by its number and size. The program replies `Locker 12 added.`\n\nA locker is given to a member with `assign`, followed by the locker number, the member's name and card number. If the locker is free, the program replies `Locker 12 assigned to Marek.` If someone already uses it, it replies `Locker 12 is taken.` If there is no such locker, it replies `Locker 99 does not exist.`\n\nThe command `count` prints how many lockers are free and how many are taken, in exactly this form: `Free lockers: 2, taken lockers: 1.`\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie skrinky","name_en":"Adding a locker","input":"addlocker 12 large\naddlocker 13 small\nexit\n","expected":"Locker 12 added.\nLocker 13 added.\n","points":15},{"name_sk":"Pridelenie voľnej skrinky priradí člena","name_en":"Assigning a free locker assigns the member","input":"addlocker 12 large\naddlocker 13 small\nassign 12 Marek M001\ncount\nexit\n","expected":"Locker 12 added.\nLocker 13 added.\nLocker 12 assigned to Marek.\nFree lockers: 1, taken lockers: 1.\n","points":25},{"name_sk":"Pridelenie obsadenej skrinky zlyhá","name_en":"Assigning a taken locker fails","input":"addlocker 12 large\nassign 12 Marek M001\nassign 12 Zuzana M002\ncount\nexit\n","expected":"Locker 12 added.\nLocker 12 assigned to Marek.\nLocker 12 is taken.\nFree lockers: 0, taken lockers: 1.\n","points":20},{"name_sk":"Počty voľných a obsadených skriniek sú presné","name_en":"The free and taken counts are exact","input":"count\naddlocker 12 large\naddlocker 13 small\naddlocker 14 large\ncount\nassign 14 Zuzana M002\nassign 13 Marek M001\ncount\nexit\n","expected":"Free lockers: 0, taken lockers: 0.\nLocker 12 added.\nLocker 13 added.\nLocker 14 added.\nFree lockers: 3, taken lockers: 0.\nLocker 14 assigned to Zuzana.\nLocker 13 assigned to Marek.\nFree lockers: 1, taken lockers: 2.\n","points":25},{"name_sk":"Pridelenie neexistujúcej skrinky zlyhá","name_en":"Assigning a locker that does not exist fails","input":"addlocker 12 large\nassign 99 Marek M001\ncount\nexit\n","expected":"Locker 12 added.\nLocker 99 does not exist.\nFree lockers: 1, taken lockers: 0.\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Locker","role":"item","properties":["int Number","string Size","Member? Member","bool IsFree (Member == null)"]},{"name":"Member","role":"person","properties":["string Name","string CardId"]},{"name":"Gym","role":"manager","properties":["string Name","List<Locker> Lockers"],"operations":["AddLocker(number, size)","Assign(number, member)","CountFree() / CountTaken()"]}],"link":"Locker.Member → Member (one-way: the locker knows who uses it)","storage":"List<Locker> in Gym"}$q$::jsonb,
        ($q$"// Reference solution – Sila Fitness. Hidden from students; used to validate the scenarios.\nvar gym = new Gym(\"Sila\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addlocker\")\n    {\n        Console.WriteLine(gym.AddLocker(int.Parse(parts[1]), parts[2]));\n    }\n    else if (command == \"assign\")\n    {\n        Console.WriteLine(gym.Assign(int.Parse(parts[1]), new Member(parts[2], parts[3])));\n    }\n    else if (command == \"count\")\n    {\n        Console.WriteLine($\"Free lockers: {gym.CountFree()}, taken lockers: {gym.CountTaken()}.\");\n    }\n}\n\nclass Locker\n{\n    public int Number { get; }\n    public string Size { get; }\n    public Member? Member { get; set; }\n    public bool IsFree => Member == null;\n\n    public Locker(int number, string size)\n    {\n        Number = number;\n        Size = size;\n    }\n}\n\nclass Member\n{\n    public string Name { get; }\n    public string CardId { get; }\n\n    public Member(string name, string cardId)\n    {\n        Name = name;\n        CardId = cardId;\n    }\n}\n\nclass Gym\n{\n    public string Name { get; }\n    private readonly List<Locker> lockers = new List<Locker>();\n\n    public Gym(string name)\n    {\n        Name = name;\n    }\n\n    public string AddLocker(int number, string size)\n    {\n        lockers.Add(new Locker(number, size));\n        return $\"Locker {number} added.\";\n    }\n\n    public string Assign(int number, Member member)\n    {\n        Locker? locker = lockers.Find(l => l.Number == number);\n        if (locker == null) return $\"Locker {number} does not exist.\";\n        if (!locker.IsFree) return $\"Locker {number} is taken.\";\n        locker.Member = member;\n        return $\"Locker {number} assigned to {member.Name}.\";\n    }\n\n    public int CountFree()\n    {\n        return lockers.FindAll(l => l.IsFree).Count;\n    }\n\n    public int CountTaken()\n    {\n        return lockers.Count - CountFree();\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
