insert into quiz.assignments (slug, sort_order, is_active, title_sk, title_en, brief_sk, brief_en,
                              max_points, time_limit_ms, scenarios, design, reference_solution)
values ($q$hotel$q$, 10, true, $q$Hotel Tatra$q$, $q$Hotel Tatra$q$,
        ($q$"Majiteľ malého Hotela Tatra chce jednoduchý konzolový program pre recepciu. Hotel má izby a každá izba má číslo a typ, napríklad single alebo double. V izbách bývajú hostia a recepčná potrebuje poznať meno a e-mail každého hosťa.\n\nRecepčná musí vedieť pridať novú izbu príkazom `addroom`, za ktorým nasleduje číslo a typ izby. Program odpovie `Room 101 added.`\n\nMusí vedieť izbu rezervovať príkazom `book`, za ktorým nasleduje číslo izby, meno a e-mail hosťa. Ak je izba voľná, program odpovie `Room 101 booked for John.` Ak je už obsadená, odpovie `Room 101 is not available.` Ak izba neexistuje, odpovie `Room 999 does not exist.`\n\nNapokon príkaz `free` vypíše každú voľnú izbu na samostatný riadok, napríklad `101 double`, v poradí, v akom boli izby pridané. Ak nie je voľná žiadna izba, vypíše `No free rooms.`\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"The owner of the small Hotel Tatra wants a simple console program for the reception desk. The hotel has rooms, and each room has a number and a type, like single or double. Guests stay in rooms, and the receptionist needs to know each guest's name and email.\n\nThe receptionist must be able to add a new room with the command `addroom`, followed by the room number and type. The program replies `Room 101 added.`\n\nThey must be able to book a room with `book`, followed by the room number, the guest's name and email. If the room is free, the program replies `Room 101 booked for John.` If it is already taken, it replies `Room 101 is not available.` If the room does not exist, it replies `Room 999 does not exist.`\n\nFinally, the command `free` lists every free room on its own line, like `101 double`, in the order the rooms were added. If no room is free, it prints `No free rooms.`\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie izby","name_en":"Adding a room","input":"addroom 101 double\naddroom 102 single\nexit\n","expected":"Room 101 added.\nRoom 102 added.\n","points":15},{"name_sk":"Rezervácia voľnej izby priradí hosťa a izba už nie je voľná","name_en":"Booking a free room assigns the guest and marks the room taken","input":"addroom 101 double\naddroom 102 single\nbook 101 John john@mail.sk\nfree\nexit\n","expected":"Room 101 added.\nRoom 102 added.\nRoom 101 booked for John.\n102 single\n","points":25},{"name_sk":"Rezervácia obsadenej izby zlyhá","name_en":"Booking a taken room fails","input":"addroom 101 double\nbook 101 John john@mail.sk\nbook 101 Anna anna@mail.sk\nexit\n","expected":"Room 101 added.\nRoom 101 booked for John.\nRoom 101 is not available.\n","points":20},{"name_sk":"Zoznam voľných izieb obsahuje presne prázdne izby","name_en":"The free-room list shows exactly the empty rooms","input":"addroom 101 double\naddroom 102 single\naddroom 103 double\nfree\nbook 102 Anna anna@mail.sk\nbook 101 John john@mail.sk\nfree\nbook 103 Eva eva@mail.sk\nfree\nexit\n","expected":"Room 101 added.\nRoom 102 added.\nRoom 103 added.\n101 double\n102 single\n103 double\nRoom 102 booked for Anna.\nRoom 101 booked for John.\n103 double\nRoom 103 booked for Eva.\nNo free rooms.\n","points":25},{"name_sk":"Rezervácia neexistujúcej izby zlyhá","name_en":"Booking a room that does not exist fails","input":"addroom 101 double\nbook 999 John john@mail.sk\nfree\nexit\n","expected":"Room 101 added.\nRoom 999 does not exist.\n101 double\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Room","role":"item","properties":["int Number","string Type","Guest? Guest","bool IsFree (Guest == null)"]},{"name":"Guest","role":"person","properties":["string Name","string Email"]},{"name":"Hotel","role":"manager","properties":["string Name","List<Room> Rooms"],"operations":["AddRoom(number, type)","Book(number, guest)","FreeRooms()"]}],"link":"Room.Guest → Guest (one-way: the room knows its guest)","storage":"List<Room> in Hotel"}$q$::jsonb,
        ($q$"// Reference solution – Hotel Tatra. Hidden from students; used to validate the scenarios.\nvar hotel = new Hotel(\"Tatra\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addroom\")\n    {\n        Console.WriteLine(hotel.AddRoom(int.Parse(parts[1]), parts[2]));\n    }\n    else if (command == \"book\")\n    {\n        Console.WriteLine(hotel.Book(int.Parse(parts[1]), new Guest(parts[2], parts[3])));\n    }\n    else if (command == \"free\")\n    {\n        List<Room> free = hotel.FreeRooms();\n        if (free.Count == 0) Console.WriteLine(\"No free rooms.\");\n        foreach (Room room in free) Console.WriteLine($\"{room.Number} {room.Type}\");\n    }\n}\n\nclass Room\n{\n    public int Number { get; }\n    public string Type { get; }\n    public Guest? Guest { get; set; }\n    public bool IsFree => Guest == null;\n\n    public Room(int number, string type)\n    {\n        Number = number;\n        Type = type;\n    }\n}\n\nclass Guest\n{\n    public string Name { get; }\n    public string Email { get; }\n\n    public Guest(string name, string email)\n    {\n        Name = name;\n        Email = email;\n    }\n}\n\nclass Hotel\n{\n    public string Name { get; }\n    private readonly List<Room> rooms = new List<Room>();\n\n    public Hotel(string name)\n    {\n        Name = name;\n    }\n\n    public string AddRoom(int number, string type)\n    {\n        rooms.Add(new Room(number, type));\n        return $\"Room {number} added.\";\n    }\n\n    public string Book(int number, Guest guest)\n    {\n        Room? room = rooms.Find(r => r.Number == number);\n        if (room == null) return $\"Room {number} does not exist.\";\n        if (!room.IsFree) return $\"Room {number} is not available.\";\n        room.Guest = guest;\n        return $\"Room {number} booked for {guest.Name}.\";\n    }\n\n    public List<Room> FreeRooms()\n    {\n        return rooms.FindAll(r => r.IsFree);\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
