values ($q$library$q$, 20, true, $q$Obecná knižnica$q$, $q$Village Library$q$,
        ($q$"Obecná knižnica v Lúčkach požičiava knihy čitateľom a chce prestať používať papierové lístky. Každá kniha má kód a názov. Každý čitateľ má meno a číslo čitateľského preukazu a knihovníčka musí vždy vedieť, kto si požičal ktorú knihu.\n\nKnihovníčka pridá novú knihu príkazom `addbook`, za ktorým nasleduje kód a názov knihy. Program odpovie `Book B1 added.`\n\nČitateľ si knihu požičia príkazom `borrow`, za ktorým nasleduje kód knihy, meno čitateľa a číslo preukazu. Ak je kniha v regáli, program odpovie `Book B1 borrowed by Eva.` Ak ju už niekto má, odpovie `Book B1 is already borrowed.` Ak kniha s takým kódom neexistuje, odpovie `Book B9 does not exist.`\n\nPríkaz `borrowed` vypíše každú požičanú knihu na samostatný riadok s kódom, názvom a menom čitateľa, napríklad `B1 Hobbit - Eva`, v poradí, v akom boli knihy pridané. Ak nie je požičaná žiadna kniha, vypíše `No borrowed books.`\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"The village library in Lúčky lends books to its readers and wants to stop using paper cards. Every book has a code and a title. Every reader has a name and a library card number, and the librarian must always know who has borrowed which book.\n\nThe librarian adds a new book with the command `addbook`, followed by the book's code and title. The program replies `Book B1 added.`\n\nA reader borrows a book with `borrow`, followed by the book's code, the reader's name and card number. If the book is on the shelf, the program replies `Book B1 borrowed by Eva.` If someone already has it, it replies `Book B1 is already borrowed.` If there is no book with that code, it replies `Book B9 does not exist.`\n\nThe command `borrowed` lists every borrowed book on its own line with the code, the title and the reader's name, like `B1 Hobbit - Eva`, in the order the books were added. If no book is borrowed, it prints `No borrowed books.`\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie knihy","name_en":"Adding a book","input":"addbook B1 Hobbit\naddbook B2 Matilda\nexit\n","expected":"Book B1 added.\nBook B2 added.\n","points":15},{"name_sk":"Požičanie voľnej knihy priradí čitateľa","name_en":"Borrowing a free book assigns the reader","input":"addbook B1 Hobbit\naddbook B2 Matilda\nborrow B2 Eva C100\nborrowed\nexit\n","expected":"Book B1 added.\nBook B2 added.\nBook B2 borrowed by Eva.\nB2 Matilda - Eva\n","points":25},{"name_sk":"Požičanie už požičanej knihy zlyhá","name_en":"Borrowing a book that is already borrowed fails","input":"addbook B1 Hobbit\nborrow B1 Eva C100\nborrow B1 Tomas C200\nexit\n","expected":"Book B1 added.\nBook B1 borrowed by Eva.\nBook B1 is already borrowed.\n","points":20},{"name_sk":"Zoznam požičaných kníh je presný","name_en":"The list of borrowed books is exact","input":"addbook B1 Hobbit\naddbook B2 Matilda\naddbook B3 Dune\nborrowed\nborrow B3 Tomas C200\nborrow B1 Eva C100\nborrowed\nexit\n","expected":"Book B1 added.\nBook B2 added.\nBook B3 added.\nNo borrowed books.\nBook B3 borrowed by Tomas.\nBook B1 borrowed by Eva.\nB1 Hobbit - Eva\nB3 Dune - Tomas\n","points":25},{"name_sk":"Požičanie neexistujúcej knihy zlyhá","name_en":"Borrowing a book that does not exist fails","input":"addbook B1 Hobbit\nborrow B9 Eva C100\nborrowed\nexit\n","expected":"Book B1 added.\nBook B9 does not exist.\nNo borrowed books.\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Book","role":"item","properties":["string Code","string Title","Reader? Reader","bool IsBorrowed (Reader != null)"]},{"name":"Reader","role":"person","properties":["string Name","string CardNumber"]},{"name":"Library","role":"manager","properties":["string Name","List<Book> Books"],"operations":["AddBook(code, title)","Borrow(code, reader)","BorrowedBooks()"]}],"link":"Book.Reader → Reader (one-way: the book knows who has it)","storage":"List<Book> in Library"}$q$::jsonb,
        ($q$"// Reference solution – Village Library. Hidden from students; used to validate the scenarios.\nvar library = new Library(\"Lucky\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addbook\")\n    {\n        Console.WriteLine(library.AddBook(parts[1], parts[2]));\n    }\n    else if (command == \"borrow\")\n    {\n        Console.WriteLine(library.Borrow(parts[1], new Reader(parts[2], parts[3])));\n    }\n    else if (command == \"borrowed\")\n    {\n        List<Book> borrowed = library.BorrowedBooks();\n        if (borrowed.Count == 0) Console.WriteLine(\"No borrowed books.\");\n        foreach (Book book in borrowed) Console.WriteLine($\"{book.Code} {book.Title} - {book.Reader!.Name}\");\n    }\n}\n\nclass Book\n{\n    public string Code { get; }\n    public string Title { get; }\n    public Reader? Reader { get; set; }\n    public bool IsBorrowed => Reader != null;\n\n    public Book(string code, string title)\n    {\n        Code = code;\n        Title = title;\n    }\n}\n\nclass Reader\n{\n    public string Name { get; }\n    public string CardNumber { get; }\n\n    public Reader(string name, string cardNumber)\n    {\n        Name = name;\n        CardNumber = cardNumber;\n    }\n}\n\nclass Library\n{\n    public string Name { get; }\n    private readonly List<Book> books = new List<Book>();\n\n    public Library(string name)\n    {\n        Name = name;\n    }\n\n    public string AddBook(string code, string title)\n    {\n        books.Add(new Book(code, title));\n        return $\"Book {code} added.\";\n    }\n\n    public string Borrow(string code, Reader reader)\n    {\n        Book? book = books.Find(b => b.Code == code);\n        if (book == null) return $\"Book {code} does not exist.\";\n        if (book.IsBorrowed) return $\"Book {code} is already borrowed.\";\n        book.Reader = reader;\n        return $\"Book {code} borrowed by {reader.Name}.\";\n    }\n\n    public List<Book> BorrowedBooks()\n    {\n        return books.FindAll(b => b.IsBorrowed);\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
