values ($q$parking-garage$q$, 60, true, $q$Parkovací dom Centrum$q$, $q$Centrum Parking Garage$q$,
        ($q$"Parkovací dom Centrum v Košiciach prenajíma parkovacie miesta stálym vodičom. Každé miesto má číslo a poschodie, na ktorom sa nachádza. Každý vodič má meno a ŠPZ svojho auta a obsluha musí vedieť, ktorý vodič parkuje na ktorom mieste.\n\nObsluha pridá miesto príkazom `addspot`, za ktorým nasleduje číslo miesta a číslo poschodia. Program odpovie `Spot 5 added.`\n\nVodič zaparkuje príkazom `park`, za ktorým nasleduje číslo miesta, meno vodiča a ŠPZ. Ak je miesto prázdne, program odpovie `Jana parked at spot 5.` Ak je už obsadené, odpovie `Spot 5 is occupied.` Ak také miesto neexistuje, odpovie `Spot 50 does not exist.`\n\nPríkaz `find`, za ktorým nasleduje ŠPZ, povie, kde to auto stojí: `Car KE456CD is at spot 5 on floor 1.`, alebo `Car KE456CD is not in the garage.`, ak vodič s takou ŠPZ nezaparkoval.\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"Centrum Parking Garage in Košice rents parking spots to regular drivers. Every spot has a number and the floor it is on. Every driver has a name and the licence plate of their car, and the attendant must know which driver has parked in which spot.\n\nThe attendant adds a spot with the command `addspot`, followed by the spot number and the floor number. The program replies `Spot 5 added.`\n\nA driver parks with `park`, followed by the spot number, the driver's name and licence plate. If the spot is empty, the program replies `Jana parked at spot 5.` If it is already occupied, it replies `Spot 5 is occupied.` If there is no such spot, it replies `Spot 50 does not exist.`\n\nThe command `find`, followed by a licence plate, tells where that car is: `Car KE456CD is at spot 5 on floor 1.`, or `Car KE456CD is not in the garage.` if no driver with that plate has parked.\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie miesta","name_en":"Adding a spot","input":"addspot 5 1\naddspot 6 2\nexit\n","expected":"Spot 5 added.\nSpot 6 added.\n","points":15},{"name_sk":"Parkovanie na voľnom mieste priradí vodiča","name_en":"Parking in a free spot assigns the driver","input":"addspot 5 1\naddspot 6 2\npark 6 Jana KE456CD\nfind KE456CD\nexit\n","expected":"Spot 5 added.\nSpot 6 added.\nJana parked at spot 6.\nCar KE456CD is at spot 6 on floor 2.\n","points":25},{"name_sk":"Parkovanie na obsadenom mieste zlyhá","name_en":"Parking in an occupied spot fails","input":"addspot 5 1\npark 5 Jana KE456CD\npark 5 Milan BA111AA\nfind BA111AA\nexit\n","expected":"Spot 5 added.\nJana parked at spot 5.\nSpot 5 is occupied.\nCar BA111AA is not in the garage.\n","points":20},{"name_sk":"Hľadanie auta podľa ŠPZ je presné","name_en":"Finding a car by its plate is exact","input":"addspot 1 0\naddspot 2 0\naddspot 30 3\nfind PO222BB\npark 30 Milan PO222BB\npark 1 Jana KE456CD\nfind PO222BB\nfind KE456CD\nfind BA111AA\nexit\n","expected":"Spot 1 added.\nSpot 2 added.\nSpot 30 added.\nCar PO222BB is not in the garage.\nMilan parked at spot 30.\nJana parked at spot 1.\nCar PO222BB is at spot 30 on floor 3.\nCar KE456CD is at spot 1 on floor 0.\nCar BA111AA is not in the garage.\n","points":25},{"name_sk":"Parkovanie na neexistujúcom mieste zlyhá","name_en":"Parking in a spot that does not exist fails","input":"addspot 5 1\npark 50 Jana KE456CD\nfind KE456CD\nexit\n","expected":"Spot 5 added.\nSpot 50 does not exist.\nCar KE456CD is not in the garage.\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"ParkingSpot","role":"item","properties":["int Number","int Floor","Driver? Driver","bool IsFree (Driver == null)"]},{"name":"Driver","role":"person","properties":["string Name","string Plate"]},{"name":"Garage","role":"manager","properties":["string Name","List<ParkingSpot> Spots"],"operations":["AddSpot(number, floor)","Park(number, driver)","FindCar(plate)"]}],"link":"ParkingSpot.Driver → Driver (one-way: the spot knows who parked there)","storage":"List<ParkingSpot> in Garage"}$q$::jsonb,
        ($q$"// Reference solution – Centrum Parking Garage. Hidden from students; used to validate the scenarios.\nvar garage = new Garage(\"Centrum\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addspot\")\n    {\n        Console.WriteLine(garage.AddSpot(int.Parse(parts[1]), int.Parse(parts[2])));\n    }\n    else if (command == \"park\")\n    {\n        Console.WriteLine(garage.Park(int.Parse(parts[1]), new Driver(parts[2], parts[3])));\n    }\n    else if (command == \"find\")\n    {\n        string plate = parts[1];\n        ParkingSpot? spot = garage.FindCar(plate);\n        if (spot == null) Console.WriteLine($\"Car {plate} is not in the garage.\");\n        else Console.WriteLine($\"Car {plate} is at spot {spot.Number} on floor {spot.Floor}.\");\n    }\n}\n\nclass ParkingSpot\n{\n    public int Number { get; }\n    public int Floor { get; }\n    public Driver? Driver { get; set; }\n    public bool IsFree => Driver == null;\n\n    public ParkingSpot(int number, int floor)\n    {\n        Number = number;\n        Floor = floor;\n    }\n}\n\nclass Driver\n{\n    public string Name { get; }\n    public string Plate { get; }\n\n    public Driver(string name, string plate)\n    {\n        Name = name;\n        Plate = plate;\n    }\n}\n\nclass Garage\n{\n    public string Name { get; }\n    private readonly List<ParkingSpot> spots = new List<ParkingSpot>();\n\n    public Garage(string name)\n    {\n        Name = name;\n    }\n\n    public string AddSpot(int number, int floor)\n    {\n        spots.Add(new ParkingSpot(number, floor));\n        return $\"Spot {number} added.\";\n    }\n\n    public string Park(int number, Driver driver)\n    {\n        ParkingSpot? spot = spots.Find(s => s.Number == number);\n        if (spot == null) return $\"Spot {number} does not exist.\";\n        if (!spot.IsFree) return $\"Spot {number} is occupied.\";\n        spot.Driver = driver;\n        return $\"{driver.Name} parked at spot {number}.\";\n    }\n\n    public ParkingSpot? FindCar(string plate)\n    {\n        return spots.Find(s => s.Driver != null && s.Driver.Plate == plate);\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
  title_sk = excluded.title_sk, title_en = excluded.title_en,
  brief_sk = excluded.brief_sk, brief_en = excluded.brief_en,
  max_points = excluded.max_points, time_limit_ms = excluded.time_limit_ms,
  scenarios = excluded.scenarios, design = excluded.design,
  reference_solution = excluded.reference_solution, updated_at = now();

-- school-cafeteria (pending)
insert into quiz.assignments (slug, sort_order, is_active, title_sk, title_en, brief_sk, brief_en,
                              max_points, time_limit_ms, scenarios, design, reference_solution)
values ($q$school-cafeteria$q$, 80, true, $q$Školská jedáleň$q$, $q$School Cafeteria$q$,
        ($q$"Školská jedáleň na gymnáziu v Poprade varí každý deň niekoľko špeciálnych diétnych porcií a študenti si ich musia vopred rezervovať. Každá porcia má kód a názov jedla. Každý študent má meno a triedu a kuchárka musí vedieť, ktorý študent si rezervoval ktorú porciu.\n\nKuchárka pridá porciu príkazom `addportion`, za ktorým nasleduje jej kód a jedlo. Program odpovie `Portion P1 added.`\n\nŠtudent si porciu rezervuje príkazom `reserve`, za ktorým nasleduje kód porcie, meno študenta a jeho trieda. Ak je porcia ešte voľná, program odpovie `Portion P1 reserved for Tomas (1A).` Ak je už rezervovaná, odpovie `Portion P1 is already reserved.` Ak taká porcia neexistuje, odpovie `Portion P9 does not exist.`\n\nPríkaz `class`, za ktorým nasleduje trieda, vypíše každú porciu, ktorú si rezervoval študent z tejto triedy, na samostatný riadok, napríklad `P1 risotto Tomas` (kód, jedlo, študent), v poradí, v akom boli porcie pridané. Ak taká porcia nie je, vypíše `No portions for class 1A.` (s triedou, na ktorú sa pýtame).\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"The school cafeteria at the grammar school in Poprad cooks a few special diet portions every day, and students must reserve them in advance. Every portion has a code and the name of the dish. Every student has a name and a class, and the cook must know which student has reserved which portion.\n\nThe cook adds a portion with the command `addportion`, followed by its code and the dish. The program replies `Portion P1 added.`\n\nA student reserves a portion with `reserve`, followed by the portion code, the student's name and class. If the portion is still free, the program replies `Portion P1 reserved for Tomas (1A).` If it is already reserved, it replies `Portion P1 is already reserved.` If there is no such portion, it replies `Portion P9 does not exist.`\n\nThe command `class`, followed by a class, lists every portion reserved by a student of that class on its own line, like `P1 risotto Tomas` (code, dish, student), in the order the portions were added. If there is none, it prints `No portions for class 1A.` (with the class that was asked for).\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie porcie","name_en":"Adding a portion","input":"addportion P1 risotto\naddportion P2 pasta\nexit\n","expected":"Portion P1 added.\nPortion P2 added.\n","points":15},{"name_sk":"Rezervácia voľnej porcie priradí študenta","name_en":"Reserving a free portion assigns the student","input":"addportion P1 risotto\naddportion P2 pasta\nreserve P2 Tomas 1A\nclass 1A\nexit\n","expected":"Portion P1 added.\nPortion P2 added.\nPortion P2 reserved for Tomas (1A).\nP2 pasta Tomas\n","points":25},{"name_sk":"Rezervácia rezervovanej porcie zlyhá","name_en":"Reserving a portion that is already reserved fails","input":"addportion P1 risotto\nreserve P1 Tomas 1A\nreserve P1 Nina 2B\nclass 2B\nexit\n","expected":"Portion P1 added.\nPortion P1 reserved for Tomas (1A).\nPortion P1 is already reserved.\nNo portions for class 2B.\n","points":20},{"name_sk":"Zoznam porcií triedy je presný","name_en":"The list of a class's portions is exact","input":"addportion P1 risotto\naddportion P2 pasta\naddportion P3 soup\nclass 1A\nreserve P3 Nina 1A\nreserve P2 Adam 2B\nreserve P1 Tomas 1A\nclass 1A\nclass 2B\nexit\n","expected":"Portion P1 added.\nPortion P2 added.\nPortion P3 added.\nNo portions for class 1A.\nPortion P3 reserved for Nina (1A).\nPortion P2 reserved for Adam (2B).\nPortion P1 reserved for Tomas (1A).\nP1 risotto Tomas\nP3 soup Nina\nP2 pasta Adam\n","points":25},{"name_sk":"Rezervácia neexistujúcej porcie zlyhá","name_en":"Reserving a portion that does not exist fails","input":"addportion P1 risotto\nreserve P9 Tomas 1A\nclass 1A\nexit\n","expected":"Portion P1 added.\nPortion P9 does not exist.\nNo portions for class 1A.\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Portion","role":"item","properties":["string Code","string Dish","Student? Student","bool IsFree (Student == null)"]},{"name":"Student","role":"person","properties":["string Name","string ClassName"]},{"name":"Cafeteria","role":"manager","properties":["string Name","List<Portion> Portions"],"operations":["AddPortion(code, dish)","Reserve(code, student)","PortionsOfClass(className)"]}],"link":"Portion.Student → Student (one-way: the portion knows who reserved it)","storage":"List<Portion> in Cafeteria"}$q$::jsonb,
        ($q$"// Reference solution – School Cafeteria. Hidden from students; used to validate the scenarios.\nvar cafeteria = new Cafeteria(\"Poprad\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addportion\")\n    {\n        Console.WriteLine(cafeteria.AddPortion(parts[1], parts[2]));\n    }\n    else if (command == \"reserve\")\n    {\n        Console.WriteLine(cafeteria.Reserve(parts[1], new Student(parts[2], parts[3])));\n    }\n    else if (command == \"class\")\n    {\n        string className = parts[1];\n        List<Portion> portions = cafeteria.PortionsOfClass(className);\n        if (portions.Count == 0) Console.WriteLine($\"No portions for class {className}.\");\n        foreach (Portion p in portions) Console.WriteLine($\"{p.Code} {p.Dish} {p.Student!.Name}\");\n    }\n}\n\nclass Portion\n{\n    public string Code { get; }\n    public string Dish { get; }\n    public Student? Student { get; set; }\n    public bool IsFree => Student == null;\n\n    public Portion(string code, string dish)\n    {\n        Code = code;\n        Dish = dish;\n    }\n}\n\nclass Student\n{\n    public string Name { get; }\n    public string ClassName { get; }\n\n    public Student(string name, string className)\n    {\n        Name = name;\n        ClassName = className;\n    }\n}\n\nclass Cafeteria\n{\n    public string Name { get; }\n    private readonly List<Portion> portions = new List<Portion>();\n\n    public Cafeteria(string name)\n    {\n        Name = name;\n    }\n\n    public string AddPortion(string code, string dish)\n    {\n        portions.Add(new Portion(code, dish));\n        return $\"Portion {code} added.\";\n    }\n\n    public string Reserve(string code, Student student)\n    {\n        Portion? portion = portions.Find(p => p.Code == code);\n        if (portion == null) return $\"Portion {code} does not exist.\";\n        if (!portion.IsFree) return $\"Portion {code} is already reserved.\";\n        portion.Student = student;\n        return $\"Portion {code} reserved for {student.Name} ({student.ClassName}).\";\n    }\n\n    public List<Portion> PortionsOfClass(string className)\n    {\n        return portions.FindAll(p => p.Student != null && p.Student.ClassName == className);\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
  title_sk = excluded.title_sk, title_en = excluded.title_en,
  brief_sk = excluded.brief_sk, brief_en = excluded.brief_en,
  max_points = excluded.max_points, time_limit_ms = excluded.time_limit_ms,
  scenarios = excluded.scenarios, design = excluded.design,
  reference_solution = excluded.reference_solution, updated_at = now();

-- vet-clinic (pending)
insert into quiz.assignments (slug, sort_order, is_active, title_sk, title_en, brief_sk, brief_en,
                              max_points, time_limit_ms, scenarios, design, reference_solution)
values ($q$vet-clinic$q$, 70, true, $q$Veterinárna ambulancia Labka$q$, $q$Labka Vet Clinic$q$,
        ($q$"Veterinárna ambulancia Labka v Prešove objednáva zvieratá na vyšetrenie. Ambulancia ponúka termíny; každý termín má čas, napríklad 09:00, a meno veterinára, ktorý vtedy ordinuje. Každý majiteľ má meno a meno svojho zvieraťa a sestra musí vedieť, ktorý majiteľ si objednal ktorý termín.\n\nSestra pridá termín príkazom `addslot`, za ktorým nasleduje čas a meno veterinára. Program odpovie `Slot 09:00 added.`\n\nMajiteľ si termín objedná príkazom `book`, za ktorým nasleduje čas, meno majiteľa a meno zvieraťa. Ak je termín voľný, program odpovie `Slot 09:00 booked for Ema with Rex.` Ak je už obsadený, odpovie `Slot 09:00 is already booked.` Ak termín v taký čas neexistuje, odpovie `Slot 18:00 does not exist.`\n\nPríkaz `schedule` vypíše každý termín na samostatný riadok v poradí, v akom boli termíny pridané: obsadený termín ako `09:00 Novak Ema Rex` (čas, veterinár, majiteľ, zviera) a voľný ako `10:00 Kral free`. Ak nie je žiadny termín, vypíše `No slots.`\n\nProgram číta jeden príkaz na riadok a skončí príkazom `exit`. Každá hodnota v príkaze je jedno slovo. Okrem uvedených odpovedí program nevypisuje nič – žiadne menu, uvítanie ani výzvy na zadanie. Odpovede píš presne tak, ako sú uvedené (po anglicky)."$q$::jsonb #>> '{}'),
        ($q$"Labka Vet Clinic in Prešov books appointments for pets. The clinic offers appointment slots; every slot has a time, like 09:00, and the name of the vet who works then. Every pet owner has a name and the name of their pet, and the nurse must know which owner has booked which slot.\n\nThe nurse adds a slot with the command `addslot`, followed by the time and the vet's name. The program replies `Slot 09:00 added.`\n\nAn owner books a slot with `book`, followed by the time, the owner's name and the pet's name. If the slot is free, the program replies `Slot 09:00 booked for Ema with Rex.` If it is already booked, it replies `Slot 09:00 is already booked.` If there is no slot at that time, it replies `Slot 18:00 does not exist.`\n\nThe command `schedule` prints every slot on its own line, in the order the slots were added: a booked slot as `09:00 Novak Ema Rex` (time, vet, owner, pet) and a free one as `10:00 Kral free`. If there are no slots, it prints `No slots.`\n\nThe program reads one command per line and ends with the command `exit`. Every value in a command is a single word. Apart from the replies above, the program prints nothing – no menu, no welcome text, no prompts."$q$::jsonb #>> '{}'),
        100, 3000,
        $q$[{"name_sk":"Pridanie termínu","name_en":"Adding a slot","input":"addslot 09:00 Novak\naddslot 10:00 Kral\nexit\n","expected":"Slot 09:00 added.\nSlot 10:00 added.\n","points":15},{"name_sk":"Objednanie voľného termínu priradí majiteľa","name_en":"Booking a free slot assigns the owner","input":"addslot 09:00 Novak\naddslot 10:00 Kral\nbook 10:00 Ema Rex\nschedule\nexit\n","expected":"Slot 09:00 added.\nSlot 10:00 added.\nSlot 10:00 booked for Ema with Rex.\n09:00 Novak free\n10:00 Kral Ema Rex\n","points":25},{"name_sk":"Objednanie obsadeného termínu zlyhá","name_en":"Booking a slot that is already booked fails","input":"addslot 09:00 Novak\nbook 09:00 Ema Rex\nbook 09:00 Igor Micka\nschedule\nexit\n","expected":"Slot 09:00 added.\nSlot 09:00 booked for Ema with Rex.\nSlot 09:00 is already booked.\n09:00 Novak Ema Rex\n","points":20},{"name_sk":"Rozpis termínov je presný","name_en":"The schedule is exact","input":"schedule\naddslot 08:30 Kral\naddslot 09:00 Novak\naddslot 09:30 Kral\nbook 09:30 Igor Micka\nbook 08:30 Ema Rex\nschedule\nexit\n","expected":"No slots.\nSlot 08:30 added.\nSlot 09:00 added.\nSlot 09:30 added.\nSlot 09:30 booked for Igor with Micka.\nSlot 08:30 booked for Ema with Rex.\n08:30 Kral Ema Rex\n09:00 Novak free\n09:30 Kral Igor Micka\n","points":25},{"name_sk":"Objednanie neexistujúceho termínu zlyhá","name_en":"Booking a slot that does not exist fails","input":"addslot 09:00 Novak\nbook 18:00 Ema Rex\nschedule\nexit\n","expected":"Slot 09:00 added.\nSlot 18:00 does not exist.\n09:00 Novak free\n","points":15}]$q$::jsonb,
        $q${"classes":[{"name":"Slot","role":"item","properties":["string Time","string Vet","Owner? Owner","bool IsFree (Owner == null)"]},{"name":"Owner","role":"person","properties":["string Name","string PetName"]},{"name":"Clinic","role":"manager","properties":["string Name","List<Slot> Slots"],"operations":["AddSlot(time, vet)","Book(time, owner)","Schedule()"]}],"link":"Slot.Owner → Owner (one-way: the slot knows who booked it)","storage":"List<Slot> in Clinic"}$q$::jsonb,
        ($q$"// Reference solution – Labka Vet Clinic. Hidden from students; used to validate the scenarios.\nvar clinic = new Clinic(\"Labka\");\n\nwhile (true)\n{\n    string? line = Console.ReadLine();\n    if (line == null) break;\n    string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n    if (parts.Length == 0) continue;\n\n    string command = parts[0].ToLower();\n    if (command == \"exit\") break;\n\n    if (command == \"addslot\")\n    {\n        Console.WriteLine(clinic.AddSlot(parts[1], parts[2]));\n    }\n    else if (command == \"book\")\n    {\n        Console.WriteLine(clinic.Book(parts[1], new Owner(parts[2], parts[3])));\n    }\n    else if (command == \"schedule\")\n    {\n        List<Slot> slots = clinic.Schedule();\n        if (slots.Count == 0) Console.WriteLine(\"No slots.\");\n        foreach (Slot slot in slots)\n        {\n            if (slot.IsFree) Console.WriteLine($\"{slot.Time} {slot.Vet} free\");\n            else Console.WriteLine($\"{slot.Time} {slot.Vet} {slot.Owner!.Name} {slot.Owner.PetName}\");\n        }\n    }\n}\n\nclass Slot\n{\n    public string Time { get; }\n    public string Vet { get; }\n    public Owner? Owner { get; set; }\n    public bool IsFree => Owner == null;\n\n    public Slot(string time, string vet)\n    {\n        Time = time;\n        Vet = vet;\n    }\n}\n\nclass Owner\n{\n    public string Name { get; }\n    public string PetName { get; }\n\n    public Owner(string name, string petName)\n    {\n        Name = name;\n        PetName = petName;\n    }\n}\n\nclass Clinic\n{\n    public string Name { get; }\n    private readonly List<Slot> slots = new List<Slot>();\n\n    public Clinic(string name)\n    {\n        Name = name;\n    }\n\n    public string AddSlot(string time, string vet)\n    {\n        slots.Add(new Slot(time, vet));\n        return $\"Slot {time} added.\";\n    }\n\n    public string Book(string time, Owner owner)\n    {\n        Slot? slot = slots.Find(s => s.Time == time);\n        if (slot == null) return $\"Slot {time} does not exist.\";\n        if (!slot.IsFree) return $\"Slot {time} is already booked.\";\n        slot.Owner = owner;\n        return $\"Slot {time} booked for {owner.Name} with {owner.PetName}.\";\n    }\n\n    public List<Slot> Schedule()\n    {\n        return slots;\n    }\n}\n"$q$::jsonb #>> '{}'))
on conflict (slug) do update set
  sort_order = excluded.sort_order, is_active = excluded.is_active,
  title_sk = excluded.title_sk, title_en = excluded.title_en,
  brief_sk = excluded.brief_sk, brief_en = excluded.brief_en,
  max_points = excluded.max_points, time_limit_ms = excluded.time_limit_ms,
  scenarios = excluded.scenarios, design = excluded.design,
  reference_solution = excluded.reference_solution, updated_at = now();

commit;

-- check: imported assignments
select slug, is_active, title_en, jsonb_array_length(scenarios) as scenarios, max_points, updated_at
  from quiz.assignments order by sort_order, slug;
